#!/bin/bash
# mcmp117_lab_setup.sh -- creates the practice folder ~/lab used in Weeks 9-14
# (MCMP117 Fundamentals of Operating Systems / MBLP131 İşletim Sistemleri Temelleri)
#
# Usage:   bash mcmp117_lab_setup.sh          # creates ~/lab
#          bash mcmp117_lab_setup.sh /tmp/x   # creates /tmp/x/lab instead
# Safe to run again: it deletes and re-creates ONLY the lab folder.
# All data are generated by formulas (no randomness), so every student
# gets exactly the same files and the same command outputs as the slides.

BASE="${1:-$HOME}"
LAB="$BASE/lab"
case "$LAB" in */lab) ;; *) echo "refusing: unexpected path $LAB"; exit 1;; esac
rm -rf -- "$LAB"
mkdir -p "$LAB"/{docs,data,logs,src,photos,backup,scripts,projects/{alpha,beta}/{src,docs}}

# deterministic pseudo-random numbers (a linear congruential generator)
SEED=20261012
rnd() {  # rnd N  -> sets R to a number in 0..N-1
    SEED=$(( (SEED * 1103515245 + 12345) % 2147483648 ))
    R=$(( (SEED / 65536) % $1 ))
}

# ---------------------------------------------------------------- docs/
cat > "$LAB/README.txt" <<'EOF'
MCMP117 / MBLP131 Linux lab folder
==================================
docs/      short text documents
data/      students.csv, cities.txt, numbers.txt
logs/      access.log (web server) and system.log
src/       a small C program
photos/    empty "photo" files for wildcard practice
projects/  a small directory tree for navigation practice
backup/    empty -- you will copy files here
scripts/   empty -- your shell scripts go here (Week 14)
EOF
cat > "$LAB/docs/syllabus.txt" <<'EOF'
Week 1  Introduction and history
Week 2  Definitions, goals, components, structures
Week 3  OS services, system calls, processes
Week 4  Threads and CPU scheduling basics
Week 5  Scheduling algorithms and synchronization
Week 6  Memory management, paging, segmentation
Week 7  Virtual memory and file systems
Week 8  Midterm exam
Week 9  Shell basics and navigation
Week 10 File and directory operations
Week 11 Permissions, ownership and users
Week 12 Text processing and redirection
Week 13 Processes and job control
Week 14 Introduction to shell scripting
Week 15 Final exam
EOF
cat > "$LAB/docs/linux_quotes.txt" <<'EOF'
Talk is cheap. Show me the code.
Given enough eyeballs, all bugs are shallow.
Most good programmers do programming not because they expect to get paid.
Theory and practice sometimes clash. And when that happens, theory loses.
Intelligence is the ability to avoid doing work, yet getting the work done.
EOF
printf 'Final report draft.\nThis file name contains a space.\n' > "$LAB/docs/final report.txt"
printf 'editor=nano\ncolor=on\n' > "$LAB/docs/.settings"
for i in 1 2 3; do printf 'Meeting notes %d\n' "$i" > "$LAB/docs/notes_0$i.txt"; done
for p in alpha beta; do
    printf '# Project %s\n' "$p" > "$LAB/projects/$p/README.md"
    printf 'int main(void) { return 0; }\n' > "$LAB/projects/$p/src/main.c"
    printf 'Design notes for %s\n' "$p" > "$LAB/projects/$p/docs/design.txt"
done

# ---------------------------------------------------------------- data/
first=(Ahmet Ayse Mehmet Elif Can Zeynep Emre Selin Burak Deniz Murat Ece Kerem Ipek Onur Naz Arda Melis Tolga Derya)
last=(Yilmaz Kaya Demir Sahin Celik Yildiz Aydin Ozturk Arslan Dogan)
dept=(ECT ECT ECT CS CS EE ME)
{
    echo "id,name,department,midterm,final"
    for i in $(seq 1 40); do
        rnd 20; f=${first[$R]}; rnd 10; l=${last[$R]}; rnd 7; d=${dept[$R]}
        rnd 61; m=$((40 + R)); rnd 66; fi=$((35 + R))
        printf '%d,%s %s,%s,%d,%d\n' $((2026000 + i)) "$f" "$l" "$d" "$m" "$fi"
    done
} > "$LAB/data/students.csv"
cities=(Istanbul Ankara Izmir Bursa Antalya Konya Trabzon Eskisehir)
for i in $(seq 1 30); do rnd 8; echo "${cities[$R]}"; done > "$LAB/data/cities.txt"
for i in $(seq 1 20); do rnd 1000; echo "$R"; done > "$LAB/data/numbers.txt"

# ---------------------------------------------------------------- logs/
paths=(/ /index.html /about.html /courses/mcmp117 /courses/mblp131 /login /images/logo.png /api/grades /admin /robots.txt)
codes=(200 200 200 200 200 200 304 404 404 500 403 301)
months=Oct
{
    for i in $(seq 0 299); do
        rnd 6; ip="10.0.$((R + 1)).$((10 + R * 7))"
        rnd 10; p=${paths[$R]}; rnd 12; c=${codes[$R]}
        rnd 9000; b=$((R + 200)); [ "$c" = 304 ] && b=0
        h=$((8 + i / 25)); mi=$(( (i * 7) % 60 )); se=$(( (i * 13) % 60 ))
        printf '%s - - [12/%s/2026:%02d:%02d:%02d +0300] "GET %s HTTP/1.1" %s %d\n' "$ip" "$months" "$h" "$mi" "$se" "$p" "$c" "$b"
    done
} > "$LAB/logs/access.log"
levels=(INFO INFO INFO INFO INFO WARN WARN ERROR)
msgs=("disk check completed" "user login" "backup started" "backup finished" "network link up" "high memory usage" "temperature 71C" "failed to mount /dev/sdb1")
{
    for i in $(seq 0 119); do
        rnd 8; lv=${levels[$R]}
        case $lv in INFO) rnd 5; m=${msgs[$R]};; WARN) rnd 2; m=${msgs[$((5 + R))]};; ERROR) m=${msgs[7]};; esac
        h=$((9 + i / 20)); mi=$(( (i * 11) % 60 ))
        printf '2026-10-12 %02d:%02d:00 %-5s %s\n' "$h" "$mi" "$lv" "$m"
    done
} > "$LAB/logs/system.log"

# ---------------------------------------------------------------- src/ photos/
cat > "$LAB/src/hello.c" <<'EOF'
#include <stdio.h>

int main(void)
{
    printf("Hello from the lab!\n");
    return 0;
}
EOF
for i in $(seq -w 1 12); do : > "$LAB/photos/img0$i.jpg"; done
: > "$LAB/photos/img013.png"; : > "$LAB/photos/IMG_014.JPG"; : > "$LAB/photos/holiday.jpeg"

echo "Lab folder ready: $LAB"
ls "$LAB"
